import{z as i,x as B,o as r,c as p,q as A,j as l,D as e,d as E,s as t,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"ASan 的机制","description":"","frontmatter":{"title":"ASan 的机制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/asan-mechanism.md","filePath":"cs/asan-mechanism.md","lastUpdated":1791063341000}'),d={name:"cs/asan-mechanism.md"};function m(c,a,S,D,f,u){const s=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=A('<h1 id="asan-的机制" tabindex="-1">ASan 的机制 <a class="header-anchor" href="#asan-的机制" aria-label="Permalink to &quot;ASan 的机制&quot;">​</a></h1><div class="epigraph"><p>AddressSanitizer 在每个对象周围插红区，并用影子内存记录每个字节是否可访问；编译器在每次访问前插入检查。</p><footer>—— 据 Serebryany et al., AddressSanitizer, USENIX ATC 2012；LLVM/GCC 对 ASan 的文档</footer></div><p><a href="/cs/arena-allocators">上一课</a>留下的缺口接到本课。 <a href="/cs/memory-tagging">MTE</a> 是硬件粗粒度。<a href="/cs/malloc-implementation">malloc</a> 自己的 debug 钩不完整。缺口是 <strong>ASan</strong>：软件插桩 + 影子，如何接到 OS 的 mmap。内存课序在此收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>越界读可能不立刻崩。ASan：分配多拿红区，影子（常 1/8 内存）编码 poisoned。访问：把地址映射到影子，非零则报。缺口：栈、堆、全局各有插法；use-after-free 把释放块毒化并延迟真 reuse；与 <a href="/cs/fork">fork</a>、信号、[vfork] 的坑。本课不把 UBSan 的全部检查列出。</p><p><span class="marginnote">KASAN 是内核同构。硬件 ASan（MTE）可减少影子。生产一般不开完整 ASan，税是内存与指令。</span></p><p><span class="marginnote">影子为什么恰好是 1/8：影子内存每 1 字节负责描述 8 个原始字节的「可否访问」状态，所以 64 字节的对象只需 8 字节影子。64 位机器虚地址空间近乎无限，多拿这 1/8 的「地图」毫无压力，这正是 ASan 先在 64 位上普及的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链接 asan runtime：替换 malloc，mmap 影子。编译 <code>-fsanitize=address</code>。对照 memcg：ASan 进程 RSS 暴涨是影子，不是泄漏。对照 <a href="/cs/userfaultfd">userfaultfd</a>：都拦截访问，一个检测非法，一个合法填页。对照 KPTI：无关用户插桩。</p><p><span class="marginnote">「毒化（poison）」就是「在影子内存里给某段字节打上『不许碰』的记号」：分配时毒化红区、free 后毒化已释放块，之后任何一次碰它的访问都会当场报错——use-after-free 能被查出来，靠的就是这一步。</span></p>',10)),(r(),l(o,null,{default:e(()=>[t(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22load%2Fstore%22%5D%20--%3E%20SH%5B%22%E6%9F%A5%E5%BD%B1%E5%AD%90%22%5D%0A%20%20SH%20--%3E%7C%22poison%22%7C%20ABORT%5B%22%E6%8A%A5%E9%94%99%E5%9B%9E%E6%BA%AF%22%5D%0A%20%20MALLOC%5B%22asan%20malloc%22%5D%20--%3E%20RED%5B%22%E5%AF%B9%E8%B1%A1%E6%97%81%E7%BA%A2%E5%8C%BA%22%5D%0A%20%20FREE%5B%22free%22%5D%20--%3E%20POISON%5B%22%E6%AF%92%E5%8C%96%E5%B9%B6%E9%9A%94%E7%A6%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"ASan 把空间错误变成确定崩溃，是开发期的 OS 外衣：依赖 mmap 大区域、替换分配器、信号处理。它不证明无 bug。不要写成形式验证课。与竞技场：ASan 分配器通常不用生产 tcmalloc 的同一套 bin。",-1)),a[5]||(a[5]=n("p",null,"一次访问前的影子检查具体怎么做：",-1)),(r(),l(o,null,{default:e(()=>[t(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%A8%8B%E5%BA%8F%E8%A6%81%E8%AF%BB%E5%9C%B0%E5%9D%80%20p%22%5D%20--%3E%20C%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E6%8F%92%E5%85%A5%E7%9A%84%E6%A3%80%E6%9F%A5%E6%8C%87%E4%BB%A4%22%5D%0A%20%20C%20--%3E%20M%5B%22%E7%AE%97%E5%BD%B1%E5%AD%90%E5%9C%B0%E5%9D%80%20p%20%E5%8F%B3%E7%A7%BB%203%20%E4%BD%8D%E5%86%8D%E5%8A%A0%E5%9B%BA%E5%AE%9A%E5%81%8F%E7%A7%BB%22%5D%0A%20%20M%20--%3E%20L%5B%22%E8%AF%BB%E5%87%BA%E9%82%A3%201%20%E5%AD%97%E8%8A%82%E5%BD%B1%E5%AD%90%22%5D%0A%20%20L%20--%3E%20V%7B%22%E5%BD%B1%E5%AD%90%E5%80%BC%E6%98%AF%E5%90%A6%E4%B8%BA%200%22%7D%0A%20%20V%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E6%94%BE%E8%A1%8C%20%E6%89%A7%E8%A1%8C%E7%9C%9F%E6%AD%A3%E7%9A%84%E8%AF%BB%22%5D%0A%20%20V%20--%3E%7C%22%E9%9D%9E%200%22%7C%20R%5B%22%E6%8A%A5%E8%B6%8A%E7%95%8C%20%E6%89%93%E5%8D%B0%E5%88%86%E9%85%8D%E6%A0%88%E4%B8%8E%E5%9B%9E%E6%BA%AF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p>假阴性：未插桩的汇编、DMA、内核。假阳性少，但内联汇编会漏。</p><p><span class="marginnote">常见误区：初学者容易以为「ASan 跑过就等于没有内存 bug」。它只能看见被插桩代码触发的错误——未插桩的汇编、DMA 直写的缓冲、内核路径都不在监视范围内；干净跑完只说明「没被它抓到」，不是「不存在」。</span></p><p>实现上：影子通常占虚址的 1/8，64 位机器靠大空洞映射。拦截 memcpy 才能抓住块内越界。halt_on_error 与 abort 决定测试能不能继续。 读法上只引用<a href="/cs/arena-allocators">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>ASan 的机制</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 HWASAN 的历史实现细节。不保证嵌入式没有足够虚址放影子。调度进阶第一课：CFS 之后的 EEVDF。</p><p>版本字段会变，课序钉的是机制对象「ASan 的机制」，不是某一主线内核的结构体名。 后课默认：软件可用影子红区查越界。公平调度从 vruntime 走到 EEVDF，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ASan：红区 + 影子 + 编译器检查。</li><li>依赖用户 mmap 与替换 malloc；税高。</li><li>EEVDF 调度是下一单元。</li><li>出处：Serebryany et al., ATC 2012；LLVM ASan；KASAN。</li></ul>',10))])}const _=i(d,[["render",m]]);export{C as __pageData,_ as default};
